async function load(page, id = REPOSITORIES[0]) {
    await page.goto(repositoryPageUrl(id, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await ensureLoaded(explorer);
    return explorer;
}
async function ensureLoaded(explorer) {
    const loadButton = explorer.getByRole('button', { name: 'Load 100 statements', exact: true });
    await expect.poll(async () => await loadButton.isVisible() || await explorer.locator('.graph-node').count() > 0,
        { message: 'the restored graph or the confirmed empty workspace is ready' }).toBeTruthy();
    if (await loadButton.isVisible()) await loadButton.click();
    await expect(explorer.locator('.graph-node').first()).toBeAttached({ timeout: 30000 });
}
/** Opens the query editor; a graph restored after a reload may show it already, and its toggle would close it. */
async function openQueryEditor(explorer) {
    const editor = explorer.locator('#sparql');
    if (!await editor.isVisible()) await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
    await expect(editor).toBeVisible();
}
async function showAllRelationLabels(explorer) {
    const control = explorer.getByRole('button', { name: 'Show all relation labels', exact: true });
    if (await control.getAttribute('aria-pressed') !== 'true') await control.click();
}

