/** How many graphs this browser has stored for its Graph pages (the page saves its graph shortly after a change). */
async function storedWorkspaces(page) {
    return page.evaluate(() => new Promise(resolve => {
        const request = indexedDB.open('graph-field-workspaces');
        request.onerror = () => resolve(0);
        request.onsuccess = () => {
            const db = request.result;
            if (!db.objectStoreNames.contains('workspaces')) {
                db.close();
                resolve(0);
                return;
            }
            const count = db.transaction('workspaces').objectStore('workspaces').count();
            count.onsuccess = () => {
                db.close();
                resolve(count.result);
            };
            count.onerror = () => {
                db.close();
                resolve(0);
            };
        };
    }));
}

