test('other tabs update preferences and removals reset defaults while corrupt events retain the current policy',
    async ({ page, context }) => {
        const explorer = await load(page);
        const other = await context.newPage();
        await other.goto(repositoryPageUrl(REPOSITORIES[1], 'graph'));
        await waitForRoute(other, 'graph');
        const key = 'graph-field-label-policy-v1';
        await other.evaluate(([storageKey, property]) => localStorage.setItem(storageKey, JSON.stringify({
            languages: ['nb', 'en'], properties: [property], languagesConfigured: true, propertiesConfigured: true
        })), [key, RDFS]);
        await expect(explorer.locator('.graph-node[aria-label^="Alice norsk."]')).toHaveCount(1);
        await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
        await explorer.locator('.label-preferences summary').click();
        const languages = explorer.getByRole('list', { name: 'Preferred label languages' });
        await expect(languages.locator('li').first()).toContainText('nb');
        await other.evaluate(storageKey => localStorage.setItem(storageKey, '{broken'), key);
        await expect(languages.locator('li').first()).toContainText('nb');
        await other.evaluate(storageKey => localStorage.removeItem(storageKey), key);
        await expect(languages.locator('li').first()).toContainText('en');
        await expect(explorer.locator('.graph-node[aria-label^="Alice SKOS."]')).toHaveCount(1);
    });

test('browser language changes follow defaults until users configure their language order', async ({ page }) => {
    await page.addInitScript(() => Object.defineProperty(navigator, 'languages', {
        configurable: true, get: () => ['en']
    }));
    const explorer = await load(page);
    await expect(explorer.locator('.graph-node[aria-label^="Alice SKOS."]')).toHaveCount(1);
    await page.evaluate(() => {
        Object.defineProperty(navigator, 'languages', { configurable: true, get: () => ['nb', 'en'] });
        window.dispatchEvent(new Event('languagechange'));
    });
    await expect(explorer.locator('.graph-node[aria-label^="Alice norsk."]')).toHaveCount(1);
    await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
    const panel = explorer.locator('.label-preferences');
    await panel.locator('summary').click();
    await panel.getByRole('button', { name: 'Move nb later', exact: true }).click();
    await expect(explorer.locator('.graph-node[aria-label^="Alice SKOS."]')).toHaveCount(1);
    await page.evaluate(() => {
        Object.defineProperty(navigator, 'languages', { configurable: true, get: () => ['nb'] });
        window.dispatchEvent(new Event('languagechange'));
    });
    await expect(panel.getByRole('list', { name: 'Preferred label languages' }).locator('li').first()).toContainText('en');
    await panel.getByRole('button', { name: 'Use browser languages', exact: true }).click();
    await expect(explorer.locator('.graph-node[aria-label^="Alice norsk."]')).toHaveCount(1);
});

test('fast metadata labels are displayed while vocabulary discovery is still pending', async ({ page }) => {
    let gateSchema = false;
    let releaseSchema;
    const schemaGate = new Promise(resolve => { releaseSchema = resolve; });
    let schemaStarted;
    const started = new Promise(resolve => { schemaStarted = resolve; });
    await page.route(`**/repositories/${REPOSITORIES[0]}/graph`, async route => {
        if (gateSchema && route.request().method() === 'POST' && route.request().postData()?.includes('SELECT DISTINCT ?property WHERE')) {
            schemaStarted();
            await schemaGate;
        }
        await route.continue();
    });
    try {
        await page.goto(repositoryPageUrl(REPOSITORIES[0], 'graph'));
        await waitForRoute(page, 'graph');
        const explorer = page.locator('.graph-explorer');
        await expect(explorer.getByRole('button', { name: 'Load 100 statements', exact: true })).toBeVisible();
        await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
        await explorer.locator('#sparql').fill(`SELECT ?source ?predicate ?target WHERE {
            VALUES ?predicate { <https://example.org/labels/worksFor> <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> }
            ?source ?predicate ?target
        }`);
        const initialSchemaReturned = page.waitForResponse(response => response.request().postData()?.includes(
            'SELECT DISTINCT ?property WHERE') && response.status() === 200);
        await explorer.getByRole('button', { name: 'Run query', exact: true }).click();
        await (await initialSchemaReturned).finished();
        await expect(explorer.locator('.graph-node[aria-label^="Alice SKOS."]')).toHaveCount(1);
        await expect(explorer.locator('.graph-node[aria-label^="Alice SKOS."]')).toHaveAttribute('aria-label', /Person SKOS/);
        await showAllRelationLabels(explorer);
        await explorer.locator('.label-preferences summary').click();
        gateSchema = true;
        const labelsReturned = page.waitForResponse(response => response.request().postData()?.includes(
            'SELECT DISTINCT ?resource ?labelProperty ?label WHERE') && response.status() === 200);
        await explorer.getByRole('button', { name: `Remove ${SKOS}`, exact: true }).click();
        await started;
        await (await labelsReturned).finished();
        await expect(explorer.locator('.graph-node[aria-label^="Alice RDFS."]')).toHaveCount(1);
        await expect(explorer.locator('.graph-node[aria-label^="Alice RDFS."]')).toHaveAttribute('aria-label', /Person RDFS/);
        await expect(explorer.locator('.edge text', { hasText: 'employer RDFS' })).toHaveCount(1);
    } finally {
        releaseSchema();
        await page.unrouteAll({ behavior: 'wait' });
    }
});

test('default label predicate captions identify the vocabulary and distinguish HTTP from HTTPS schema', async ({ page }) => {
    await page.goto(repositoryPageUrl(REPOSITORIES[0], 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
    await explorer.locator('.label-preferences summary').click();
    const list = explorer.getByRole('list', { name: 'Preferred label predicates' });
    const captions = await list.locator('li > span').allTextContents();
    expect(new Set(captions).size).toBe(captions.length);
    await expect(list).toContainText('skos:prefLabel');
    await expect(list).toContainText('skosxl:prefLabel');
    await expect(list).toContainText('foaf:name');
    await expect(list).toContainText('schema:name (HTTPS)');
    await expect(list).toContainText('schema:name (HTTP)');
});

test('checked metadata cache reuse preserves guidance when the graph contains no label statements', async ({ page }) => {
    const query = `SELECT ?source ?predicate ?target WHERE {
        VALUES ?predicate { <https://example.org/labels/worksFor> <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> }
        ?source ?predicate ?target
    }`;
    await page.goto(repositoryPageUrl(REPOSITORIES[0], 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await expect(explorer.getByRole('button', { name: 'Load 100 statements', exact: true })).toBeVisible();
    await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
    await explorer.locator('#sparql').fill(query);
    await explorer.getByRole('button', { name: 'Run query', exact: true }).click();
    await expect(explorer.locator('.graph-node[aria-label^="Alice SKOS."]')).toHaveCount(1);
    const notice = explorer.getByRole('region', { name: 'Label preference guidance', exact: true });
    await expect(notice).toContainText('several label predicates');
    await expect(notice).toContainText('several languages');
    await expect.poll(() => page.evaluate(() => {
        const raw = localStorage.getItem('graph-field-metadata-v4');
        return raw && JSON.parse(raw).some(([key, entry]) => key.endsWith('\nhttps://example.org/labels/alice') && entry.checked);
    })).toBeTruthy();
    let metadataRequests = 0;
    page.on('request', request => {
        if (request.postData()?.includes('SELECT DISTINCT ?resource ?labelProperty ?label WHERE')) metadataRequests++;
    });
    await page.reload();
    await waitForRoute(page, 'graph');
    await expect.poll(async () => await explorer.getByRole('button', { name: 'Load 100 statements', exact: true }).isVisible()
        || await explorer.locator('.graph-node').count() > 0).toBeTruthy();
    await openQueryEditor(explorer);
    await explorer.locator('#sparql').fill(query);
    const rowsReturned = page.waitForResponse(response => response.request().postData()?.trim() === query.trim()
        && response.status() === 200);
    await explorer.getByRole('button', { name: 'Run query', exact: true }).click();
    await (await rowsReturned).finished();
    await expect(explorer.getByRole('button', { name: 'Run query', exact: true })).toBeEnabled();
    await expect(explorer.locator('.graph-node[aria-label^="Alice SKOS."]')).toHaveCount(1);
    await expect(notice).toContainText('several label predicates');
    await expect(notice).toContainText('several languages');
    expect(metadataRequests).toBe(0);
});
